get_settings.code:
final response = await client.commonSettings.getSettings(queryParams: {
  'type': 'customer_registration_field',
  'config_key': 'abn_placeholder',
});
final settings = (response.map as Map)['settings'] as Map;
for (final setting in settings['customer_registration_field'] as List) {
  print('${(setting as Map)['config_key']} ${setting['value']}');
}

update_settings.code:
final response = await client.commonSettings.updateSettings({
  'settings': {
    'customer_registration_field': [
      {'config_key': 'abn_placeholder', 'value': 'Enter your ABN'},
    ],
  },
});
final settings = (response.map as Map)['settings'] as Map;
print(settings.keys);

save_settings.code:
final response = await client.commonSettings.saveSettings({
  'settings': {
    'customer_registration_field': {'abn_placeholder': 'Enter your ABN'},
  },
});
print(response.statusCode);
print(((response.map as Map)['settings'] as Map).keys);

get_create_customer_fields.code:
final response = await client.commonSettings.getCreateCustomerFields();
final body = response.map as Map;
final configs = body['fields_configs'] as Map;
for (final field in body['fields'] as List) {
  print('${configs['${field}_label']} ${configs['${field}_required']}');
}
